window.kbPageData["views/entry/k-5d3eada523d78394"] = {"key":"entry/k-5d3eada523d78394","state":{"route":"entry/k-5d3eada523d78394"},"node":{"id":"k-5d3eada523d78394","mode":"k","title":"工作成就","type":"事实与事件","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["事实与事件"],"出处性质":["报告摘登"],"学科":["公共管理","经济"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2025,"title":"2025年政府工作回顾","slug":"e970fbcde827"}],"directorySummary":"过去一年取得的成绩来之不易。我们面对的是多年少有的外部冲击挑战和国内两难多难\n问题交织叠加的复杂严峻形势。国际经贸环境急剧变化，单边主义、保护主义陡然升级，市\n场预期受到频繁扰动，对外贸易明显承压。国内经济深刻转型，深层次结构性矛盾问题持\n续显现，消费、投资增长动力不足。以习近平同志为核心的党中央带…","sources":[{"id":"5086a85ea8f2d943","label":"工作成就","topic":"年度政府工作","category":"时政","text":"过去一年取得的成绩来之不易。我们面对的是多年少有的外部冲击挑战和国内两难多难\n问题交织叠加的复杂严峻形势。国际经贸环境急剧变化，单边主义、保护主义陡然升级，市\n场预期受到频繁扰动，对外贸易明显承压。国内经济深刻转型，深层次结构性矛盾问题持\n续显现，消费、投资增长动力不足。以习近平同志为核心的党中央带领我们沉着应对、勇\n毅前行，对外有理有力有效开展经贸斗争，坚定维护我国利益，中美 5 轮经贸磋商取得积极\n成果，两国元首釜山会晤达成重要共识，为经贸合作注入更多稳定性；对内打好政策“组合\n拳”，加强宏观政策逆周期调节①，着力稳就业、稳企业、稳市场、稳预期，集中力量办好\n自己的事。我们从最坏处打算，向最好处努力，不仅稳住了宏观经济大盘，推动高质量发展\n取得新成效，而且极大提振了全社会的士气和信心。在这个过程中，我们进一步认识到，做\n好新形势下经济工作必须充分挖掘经济潜能、必须坚持政策支持和改革创新并举、必须做\n到既“放得活”又“管得好”②、必须坚持投资于物和投资于人紧密结合③、必须以苦练内\n功来应对外部挑战。实践再次证明，坚持党中央集中统一领导是应对一切困难、做好各项工\n作的根本保证，中国人民有信心有智慧有力量战胜一切艰难险阻！","source":{"doc":"6cbfb01fe723bba64b75","first":4,"last":5,"page":4,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"dfb757aaca693d35","label":"工作成就","topic":"年度政府工作","category":"时政","text":"一年来，我国经济顶压前行、展现强大韧性。经济运行总体平稳、稳中有进，国内生产\n总值①增长 5%，总量达到 140.19 万亿元。就业总体稳定，城镇新增就业 1267 万人，城镇调\n查失业率②平均为 5.2%。对外贸易较快增长，出口多元化成效明显，国际收支基本平衡。民\n生保障更加有力，居民收入增长和经济增长同步，脱贫攻坚成果巩固拓展，实施学前一年\n免费教育政策③、惠及 1400 万儿童，全面实施育儿补贴制度④、惠及 3000 多万婴幼儿。粮食\n产量达到 1.43 万亿斤。重点领域风险化解取得积极进展，社会大局保持稳定。","source":{"doc":"6cbfb01fe723bba64b75","first":2,"last":3,"page":2,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"10b3ba48665a42f2","label":"工作成就","topic":"年度政府工作","category":"时政","text":"一年来，我国发展向新向优、彰显蓬勃活力。新质生产力稳步发展，科技创新成果丰硕，\n人工智能、生物医药、机器人、量子科技等研发应用走在世界前列，芯片自主研发有了新突\n破，天问二号①开启“追星”之旅，北斗规模应用全面拓展，雅下水电工程②开工建设，首艘\n国产电磁弹射型航母福建舰③正式入列，国产大模型④引领全球开源生态。产业结构持续优化，\n高技术制造业、装备制造业增加值分别增长 9.4%、9.2%，工业机器人、集成电路产量分别\n增长 28%、10.9%，新能源汽车年产量超过 1600 万辆，电动汽车充电设施突破 2000 万个。\n单位国内生产总值能耗降低 5.1%，生态环境质量持续改善。","source":{"doc":"6cbfb01fe723bba64b75","first":3,"last":4,"page":3,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"5fae0af5c3d9fb8d","label":"工作成就","topic":"年度政府工作","category":"时政","text":"（一）工作成就\n2025 年是很不平凡的一年。党的二十届四中全会胜利召开，擘画了未来五年我国发展\n的宏伟蓝图。我们隆重纪念中国人民抗日战争暨世界反法西斯战争胜利 80 周年①，设立台\n湾光复纪念日②，极大振奋民族精神、激发爱国热情、凝聚奋斗力量。面对国内外形势深刻\n复杂的变化，以习近平同志为核心的党中央团结带领全国各族人民迎难而上、奋力拼搏，坚\n定不移贯彻新发展理念、推动高质量发展，统筹国内国际两个大局，全年经济社会发展主要\n目标任务顺利完成，“十四五”圆满收官，中国式现代化迈出新的坚实步伐。","source":{"doc":"6cbfb01fe723bba64b75","first":2,"last":2,"page":2,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-5d3eada523d78394":[]}};
